calc.mjs.text:
// Same-ticket restaurant margin arithmetic across dine-in, pickup, and
// delivery apps. No network, no stored rate schedule: every commission and
// cost is an input. The presets below are illustrative starting points an
// operator is expected to replace with the numbers on their own statements.
// That keeps the output a transparent calculation they can check rather than
// a claim about any marketplace's current published fees.

/**
 * Illustrative defaults for the paths a ticket most often takes. Fee *shapes*
 * differ in ways a flat "DoorDash takes 30%" page hides:
 *
 *   - marketplace commission is usually a percentage of the order total and
 *     often bundles payment processing,
 *   - dine-in and pickup still pay card processing,
 *   - packaging and the extra minutes to bag a delivery order are cash the
 *     restaurant spends whether or not the app takes a cut,
 *   - first-party delivery swaps commission for a driver cost.
 *
 * `commissionRate` and `paymentRate` apply to the listed price. An operator
 * whose contract differs can zero one field and fold the rate into the other.
 */
export const CHANNEL_PRESETS = [
  {
    id: "dine-in",
    label: "Dine-in",
    note: "No marketplace commission. Card processing is usually the only platform fee. Packaging and extra delivery labor start at zero.",
    commissionRate: 0,
    paymentRate: 2.9,
    paymentFixed: 0.3,
    packagingCost: 0,
    extraLaborMinutes: 0,
    deliveryCost: 0,
  },
  {
    id: "pickup",
    label: "Pickup / takeout",
    note: "Same ticket, no marketplace cut, a bit of packaging and a few extra bagging minutes.",
    commissionRate: 0,
    paymentRate: 2.9,
    paymentFixed: 0.3,
    packagingCost: 0.4,
    extraLaborMinutes: 3,
    deliveryCost: 0,
  },
  {
    id: "doordash",
    label: "DoorDash",
    note: "Marketplace commission is usually a percentage of the order total and often includes payment processing. Plans range widely — replace this with the rate on your statement.",
    commissionRate: 27,
    paymentRate: 0,
    paymentFixed: 0,
    packagingCost: 1.25,
    extraLaborMinutes: 8,
    deliveryCost: 0,
  },
  {
    id: "ubereats",
    label: "Uber Eats",
    note: "Commission is typically a percentage of the order. Some plans add a separate processing fee — put that in the payment-rate field if yours does.",
    commissionRate: 30,
    paymentRate: 0,
    paymentFixed: 0,
    packagingCost: 1.25,
    extraLaborMinutes: 8,
    deliveryCost: 0,
  },
  {
    id: "grubhub",
    label: "Grubhub",
    note: "Commission varies by plan and market. The default here is a single bundled percentage; split processing out if your statement does.",
    commissionRate: 25,
    paymentRate: 0,
    paymentFixed: 0,
    packagingCost: 1.25,
    extraLaborMinutes: 8,
    deliveryCost: 0,
  },
  {
    id: "first-party",
    label: "Your own driver",
    note: "No marketplace commission — you pay card processing, packaging, bagging time, and whatever the driver costs on this ticket.",
    commissionRate: 0,
    paymentRate: 2.9,
    paymentFixed: 0.3,
    packagingCost: 1.25,
    extraLaborMinutes: 8,
    deliveryCost: 4.5,
  },
  {
    id: "other",
    label: "Other channel",
    note: "Blank and switched off by default. Turn it on for a second DoorDash plan, Toast Takeout, a hotel portal, or any path not listed.",
    commissionRate: 0,
    paymentRate: 0,
    paymentFixed: 0,
    packagingCost: 0,
    extraLaborMinutes: 0,
    deliveryCost: 0,
    enabled: false,
  },
];

function number(value, name, fallback = 0) {
  const raw = value === undefined || value === null || value === "" ? fallback : value;
  const result = Number(raw);
  if (!Number.isFinite(result) || result < 0) throw new Error(`${name} must be a non-negative number`);
  return result;
}

function wholeNumber(value, name, fallback = 0) {
  const result = number(value, name, fallback);
  if (!Number.isInteger(result)) throw new Error(`${name} must be a whole number`);
  return result;
}

function priceForTarget(targetProfit, percentRate, paymentFixed, cashCosts) {
  const target = Number(targetProfit);
  if (!Number.isFinite(target)) throw new Error("Target profit must be a number");
  return Math.max(0, (target + paymentFixed + cashCosts) / (1 - percentRate));
}

/**
 * Net result for one path, given the shared ticket facts.
 *
 * `shared` carries what does not change with the channel (food cost, wage,
 * the dine-in menu price used as the default listed price). A channel can
 * override the listed price so a marked-up DoorDash menu can be compared
 * against the in-house ticket.
 */
export function calculateChannel(channel, shared = {}) {
  if (!channel || typeof channel !== "object") throw new Error("A channel is required");
  const label = channel.label ?? channel.id ?? "Channel";

  const listedPrice = number(channel.listedPrice, `${label} listed price`, shared.ticketPrice);
  const foodCost = number(shared.foodCost, "Food cost", 0);
  const hourlyWage = number(shared.hourlyWage, "Hourly wage", 0);
  const monthlyOrders = wholeNumber(shared.monthlyOrders, "Orders per month", 0);

  const commissionRate = number(channel.commissionRate, `${label} commission rate`, 0);
  const paymentRate = number(channel.paymentRate, `${label} payment rate`, 0);
  const paymentFixed = number(channel.paymentFixed, `${label} payment fixed fee`, 0);
  const packagingCost = number(channel.packagingCost, `${label} packaging cost`, 0);
  const extraLaborMinutes = number(channel.extraLaborMinutes, `${label} extra labor minutes`, 0);
  const deliveryCost = number(channel.deliveryCost, `${label} delivery cost`, 0);

  const percentRate = (commissionRate + paymentRate) / 100;
  if (percentRate >= 1) {
    throw new Error(`${label}: commission and payment rates add up to 100% or more of the ticket`);
  }

  const revenue = listedPrice;
  const laborCost = (extraLaborMinutes / 60) * hourlyWage;
  const fees = {
    commission: (revenue * commissionRate) / 100,
    payment: (revenue * paymentRate) / 100 + paymentFixed,
  };
  const feeTotal = fees.commission + fees.payment;
  const cashCosts = foodCost + packagingCost + laborCost + deliveryCost;
  const profit = revenue - feeTotal - cashCosts;

  return {
    id: channel.id ?? null,
    label,
    note: channel.note ?? null,
    listedPrice,
    revenue,
    fees,
    feeTotal,
    foodCost,
    packagingCost,
    laborCost,
    deliveryCost,
    cashCosts,
    profit,
    margin: revenue === 0 ? 0 : (profit / revenue) * 100,
    foodCostPct: revenue === 0 ? 0 : (foodCost / revenue) * 100,
    percentRate: percentRate * 100,
    paymentFixed,
    monthlyOrders,
    monthlyProfit: profit * monthlyOrders,
    monthlyFees: feeTotal * monthlyOrders,
    breakEvenPrice: priceForTarget(0, percentRate, paymentFixed, cashCosts),
    /**
     * Listed price this channel needs, holding costs constant, to clear
     * `targetProfit`. This is the number that turns a comparison into a
     * menu decision: "to keep the same $21.17 as dine-in, list this at $47.15
     * on DoorDash."
     */
    priceForProfit(targetProfit) {
      return priceForTarget(targetProfit, percentRate, paymentFixed, cashCosts);
    },
    /**
     * Commission percentage that would leave `targetProfit` at the current
     * listed price, holding the payment-rate and cash costs constant.
     * Null when revenue is zero (the question has no answer). Negative when
     * extra cash (packaging, labor, driver) already exceeds the gap — the
     * listed price has to rise; cutting commission cannot close it.
     */
    commissionToMatch(targetProfit) {
      const target = Number(targetProfit);
      if (!Number.isFinite(target)) throw new Error("Target profit must be a number");
      if (revenue === 0) return null;
      return 100 * (1 - (target + fees.payment + cashCosts) / revenue) - 0;
    },
  };
}

/**
 * Rank every path on the same ticket. `channels` are preset-shaped objects;
 * anything an operator edited is already on them, anything they left alone
 * falls back to `shared`. A channel carrying `enabled: false` is left out of
 * the ranking rather than shown as an unreachable option.
 */
export function compareChannels(channels, shared = {}) {
  if (!Array.isArray(channels) || channels.length === 0) {
    throw new Error("At least one channel is required");
  }
  const active = channels.filter((channel) => channel?.enabled !== false);
  if (active.length === 0) throw new Error("Switch on at least one channel to compare");
  const results = active.map((channel) => calculateChannel(channel, shared));
  const best = results.reduce((winner, result) => (result.profit > winner.profit ? result : winner));
  const dineIn = results.find((result) => result.id === "dine-in") ?? null;

  const ranked = [...results].sort((a, b) => b.profit - a.profit);
  const rankByResult = new Map(ranked.map((result, index) => [result, index + 1]));

  return {
    results: results.map((result) => {
      const priceToMatchBest = result === best ? null : result.priceForProfit(best.profit);
      const priceToMatchDineIn =
        dineIn && result !== dineIn ? result.priceForProfit(dineIn.profit) : null;
      const markupVsDineIn =
        dineIn && priceToMatchDineIn !== null && dineIn.listedPrice > 0
          ? ((priceToMatchDineIn / dineIn.listedPrice) - 1) * 100
          : null;
      const commissionToMatchDineIn =
        dineIn && result !== dineIn ? result.commissionToMatch(dineIn.profit) : null;
      return {
        ...result,
        rank: rankByResult.get(result),
        isBest: result === best,
        gapVsBest: best.profit - result.profit,
        monthlyGapVsBest: (best.profit - result.profit) * result.monthlyOrders,
        priceToMatchBest,
        priceToMatchDineIn,
        markupVsDineIn,
        commissionToMatchDineIn,
        gapVsDineIn: dineIn ? dineIn.profit - result.profit : null,
        monthlyGapVsDineIn: dineIn ? (dineIn.profit - result.profit) * result.monthlyOrders : null,
      };
    }),
    ranked: ranked.map((result) => result.label),
    best: {
      id: best.id,
      label: best.label,
      profit: best.profit,
      margin: best.margin,
    },
    dineIn: dineIn
      ? { id: dineIn.id, label: dineIn.label, profit: dineIn.profit, listedPrice: dineIn.listedPrice }
      : null,
    // How much the path choice is worth on this one ticket, before any
    // difference in how many orders each path actually produces.
    spread: best.profit - ranked[ranked.length - 1].profit,
  };
}

share.mjs.text:
// A shareable link and a local save for one restaurant's channel comparison.
//
// Before this, the only way to hand a priced comparison to a partner or an
// accountant was "Copy decision summary" -- prose describing the winner, not
// the inputs. That is enough to report a decision but not enough to *check*
// one: a partner who wants to try a different DoorDash commission has to
// retype every field from scratch, on every channel, or take the sender's
// word for the shared and per-channel numbers that produced it.
//
// The transform is pure and takes the field list as an argument rather than
// keeping its own copy. `SHARED_FIELDS` and `CHANNEL_FIELDS` in `index.html`
// already say what `readShared()` and `renderPanels()` read and write, so
// passing those same lists in means a field added to the form is shareable
// the moment it exists. A second hand-maintained allowlist in here would
// silently drop whatever the form grew since -- a shared link that reopens a
// different comparison than the sender saw is worse than no link at all.
//
// Nothing here is transmitted. `localStorage` is the visitor's own disk, and
// the link is only ever built in the browser and copied by the visitor. The
// comparison travels in the URL *fragment* (`#...`), never the query string:
// a fragment is not sent in the request line a server logs, nor in the
// `Referer` header a later click would carry, so a restaurant's ticket price,
// food cost and commission rates stay on the machines the sender chooses to
// send the link to.

const VERSION = 1;
const ROW_SEPARATOR = ',';
const CELL_SEPARATOR = ':';
// A ceiling far above the six shipped channels plus headroom for "Other
// channel" duplicated a few times by hand -- not a limit anyone should ever
// approach, and far below anything that would slow a browser down.
const MAX_ROWS = 20;

// Only a finite, non-negative number is carried, the same contract
// `calculateChannel` enforces on every numeric input -- a restored or shared
// value can never prefill a field the calculator would then reject.
function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

/**
 * Spec shape:
 *   {
 *     key:     'delivery-app-margin',       // localStorage key
 *     numbers: ['ticketPrice', ...],        // the shared, non-channel fields
 *     rows:    { param: 'channels', fields: [...] },
 *   }
 *
 * `rows` carries the channel list. Each channel is identified by its preset
 * `id` (a `choice` cell restricted to the ids `CHANNEL_PRESETS` actually
 * ships), so a decoded row can only ever address a channel this build knows
 * about -- a crafted link cannot inject a made-up path with no rate table
 * behind it. Every other cell is the numeric rate or cost fields a channel
 * panel exposes, plus `enabled` riding as a two-value choice the same way
 * `tree-service-bid-calculator`'s per-tree checkboxes do, because a row cell
 * here is a number or a choice -- there is no boolean cell kind.
 */
export function buildSpec(sharedFields, channelFieldKeys, channelIds) {
  return {
    key: 'delivery-app-margin',
    numbers: [...sharedFields],
    rows: {
      param: 'channels',
      fields: [
        { key: 'id', kind: 'choice', options: [...channelIds] },
        ...channelFieldKeys.map((key) => ({ key, kind: 'number' })),
        { key: 'enabled', kind: 'choice', options: ['1', '0'] },
      ],
    },
  };
}

function encodeCell(field, value) {
  if (field.kind === 'choice') {
    const text = typeof value === 'string' ? value : String(value ?? '');
    return field.options.includes(text) ? text : '';
  }
  const number = usableNumber(value);
  return number === null ? '' : String(number);
}

function decodeCell(field, raw) {
  if (field.kind === 'choice') return field.options.includes(raw) ? raw : null;
  const number = usableNumber(raw);
  return number === null ? null : String(number);
}

// values: { ...sharedFields, channels: [{ id, enabled, ...rateFields }] }
// -> query string (no leading '#'). Field order follows the spec, so the
// same comparison always encodes to the same string and a copied link stays
// stable across visits.
export function encodeShare(spec, values) {
  const params = new URLSearchParams();
  for (const id of spec.numbers) {
    const value = usableNumber(values?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  const rows = spec.rows;
  if (Array.isArray(values?.[rows.param])) {
    const encoded = values[rows.param]
      .slice(0, MAX_ROWS)
      .map((row) => rows.fields.map((field) => encodeCell(field, row?.[field.key])).join(CELL_SEPARATOR))
      // A row whose id did not survive is not a channel the recipient's build
      // knows about; emitting it would give them a blank space to puzzle
      // over instead of the channel simply keeping its default.
      .filter((row) => !row.startsWith(CELL_SEPARATOR) && row !== '');
    if (encoded.length > 0) params.set(rows.param, encoded.join(ROW_SEPARATOR));
  }
  return params.toString();
}

// query string -> values object. Accepts a bare string or one with a leading
// '?' or '#'. Only ids named in the spec survive, numbers must parse, and a
// channel row only takes an id the preset list actually offers -- a crafted
// link cannot address a channel this build has no rate table for.
export function decodeShare(spec, source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const values = {};
  for (const id of spec.numbers) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) values[id] = String(value);
  }
  const rows = spec.rows;
  if (params.has(rows.param)) {
    const decoded = params.get(rows.param)
      .split(ROW_SEPARATOR)
      .slice(0, MAX_ROWS)
      .map((row) => {
        const cells = row.split(CELL_SEPARATOR);
        const out = {};
        rows.fields.forEach((field, index) => {
          const value = decodeCell(field, cells[index] ?? '');
          if (value !== null) out[field.key] = value;
        });
        return out;
      })
      // A row that survived validation with no channel id is not one the
      // sender described.
      .filter((row) => typeof row.id === 'string');
    if (decoded.length > 0) values[rows.param] = decoded;
  }
  return values;
}

// Writes the comparison to the visitor's own storage. Wrapped because a
// browser with site data blocked throws on access rather than returning
// null, and a mid-comparison visitor should not lose the page over a storage
// setting.
export function saveShare(storage, spec, values) {
  if (!storage || !spec?.key) return false;
  try {
    storage.setItem(spec.key, JSON.stringify({ v: VERSION, values: decodeShare(spec, encodeShare(spec, values)) }));
    return true;
  } catch {
    return false;
  }
}

// Reads a previously saved comparison back, re-validated through the same
// spec so a stored blob edited by hand, or written by an older build, can
// only ever produce fields this build knows about.
export function loadShare(storage, spec) {
  if (!storage || !spec?.key) return {};
  try {
    const raw = storage.getItem(spec.key);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.v !== VERSION || typeof parsed.values !== 'object') return {};
    return decodeShare(spec, encodeShare(spec, parsed.values));
  } catch {
    return {};
  }
}

export function clearShare(storage, spec) {
  if (!storage || !spec?.key) return false;
  try {
    storage.removeItem(spec.key);
    return true;
  } catch {
    return false;
  }
}

// A link wins over storage: a visitor who opens a comparison someone sent
// them means to see that comparison, not the one they last priced. Storage
// is the fallback for a plain visit. Returns the values plus which source
// answered, so the page can say so rather than silently changing numbers
// under the visitor.
export function restoreShare(spec, { hash = '', storage = null } = {}) {
  const fromLink = decodeShare(spec, hash);
  if (Object.keys(fromLink).length > 0) return { values: fromLink, source: 'link' };
  const stored = loadShare(storage, spec);
  if (Object.keys(stored).length > 0) return { values: stored, source: 'storage' };
  return { values: {}, source: 'none' };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores ticket
// prices, food costs, commissions, or any other calculator input, and never
// leaves the device. There is no server to send it to.
const KEY = "delivery-app-margin-usage";

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === "1" || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = "comparison_calculated") {
  // The stored choice is consulted here as well as passed in. The page reads
  // it into the checkbox on load and hands the checkbox back, which works —
  // but it makes the promise depend on one line of page wiring, and a caller
  // that forgets the second argument would count a visitor who opted out.
  // The module now honours its own record of the choice either way.
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(KEY) || "{}");
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(KEY, JSON.stringify(current));
  } catch {
    // A full or unavailable storage quota must never break the calculator —
    // the counter is a convenience, the arithmetic is the product.
  }
}

export function readUsage(storage = globalThis.localStorage) {
  try {
    return JSON.parse(storage?.getItem(KEY) || "{}");
  } catch {
    return {};
  }
}

// The opt-out choice is itself kept locally so the visitor does not have to
// make it again on every visit.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${KEY}-opt-out`) === "1";
  } catch {
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  try {
    if (optedOut) {
      storage?.setItem(`${KEY}-opt-out`, "1");
      storage?.removeItem(KEY);
    } else {
      storage?.removeItem(`${KEY}-opt-out`);
    }
  } catch {
    // Ignore: see recordUsage.
  }
}
